124	export function updateQuery(
125	  table: QueryTable,
126	  value: Dictionary<any>,
127	  options?: {
128	    filters?: Filter[]
129	    returning?: boolean
130	    enumArrayColumns?: string[]
131	  }
132	) {
133	  const { filters, returning, enumArrayColumns } = options ?? {}
134	  if (!filters || filters.length === 0) {
135	    throw { message: 'no filters for this update query' }
136	  }
137	  const queryColumns = Object.keys(value)
138	    .map((x) => ident(x))
139	    .join(',')
140	  let query = format(
141	    'update %1$s set (%2$s) = (select %2$s from json_populate_record(null::%1$s, %3$s))',
142	    queryTable(table),
143	    queryColumns,
144	    literal(JSON.stringify(value))
145	  )
146	  if (filters) {
147	    query = applyFilters(query, filters)
148	  }
149	  if (returning) {
150	    query +=
151	      enumArrayColumns === undefined || enumArrayColumns.length === 0
152	        ? ` returning *`
