163	function applyFilters(query: string, filters: Filter[]) {
164	  if (filters.length === 0) return query
165	  query += ` where ${filters
166	    .map((filter) => {
167	      switch (filter.operator) {
168	        case 'in':
169	          return inFilterSql(filter)
170	        case 'is':
171	          return isFilterSql(filter)
172	        default:
173	          return `${ident(filter.column)} ${filter.operator} ${filterLiteral(filter.value)}`
174	      }
175	    })
176	    .join(' and ')}`
177	  return query
178	}
179	
180	function inFilterSql(filter: Filter) {
181	  let values
182	  if (Array.isArray(filter.value)) {
183	    values = filter.value.map((x: any) => filterLiteral(x))
184	  } else {
185	    const filterValueTxt = String(filter.value)
186	    values = filterValueTxt.split(',').map((x: any) => filterLiteral(x))
187	  }
188	  return `${ident(filter.column)} ${filter.operator} (${values.join(',')})`
189	}
190	
191	function isFilterSql(filter: Filter) {
192	  const filterValueTxt = String(filter.value)
193	  switch (filterValueTxt) {
194	    case 'null':
195	    case 'false':
196	    case 'true':
197	    case 'not null':
198	      return `${ident(filter.column)} ${filter.operator} ${filterValueTxt}`
199	    default:
200	      return `${ident(filter.column)} ${filter.operator} ${filterLiteral(filter.value)}`
201	  }
202	}
203	
204	function filterLiteral(value: any) {
205	  if (typeof value === 'string') {
206	    if (value?.startsWith('ARRAY[') && value?.endsWith(']')) {
207	      return value
208	    } else {
209	      return literal(value)
210	    }
211	  }
212	  return value
213	}
214	
215	//============================================================
216	// Sort Utils
217	//============================================================
218	
219	function applySorts(query: string, sorts: Sort[]) {
220	  const validSorts = sorts.filter((sort) => sort.column)
221	  if (validSorts.length === 0) return query
222	  query += ` order by ${validSorts
223	    .map((x) => {
224	      const order = x.ascending ? 'asc' : 'desc'
225	      const nullOrder = x.nullsFirst ? 'nulls first' : 'nulls last'
226	      return `${ident(x.table)}.${ident(x.column)} ${order} ${nullOrder}`
227	    })
228	    .join(', ')}`
229	  return query
230	}
231	
232	//============================================================
233	// Misc
234	//============================================================
235	
236	function queryTable(table: QueryTable) {
237	  return `${ident(table.schema)}.${ident(table.name)}`
