import type { PGTable } from '../pg-meta-tables'
import type { PGView } from '../pg-meta-views'
import { Query } from './Query'
import type { Filter, Sort } from './types'

/**
 * Any "table-like" database object whose rows we can fetch: tables, views,
 * materialized views and foreign tables. Only tables carry primary keys, so we
 * treat that field as optional here.
 */
type TableLike = PGTable | PGView | PGForeignTable | PGMaterializedView

// [Joshen] We can probably make this reasonably high, but for now max aim to load 10kb
export const MAX_CHARACTERS = 10 * 1024

// Default number of array elements to keep before truncating
export const MAX_ARRAY_SIZE = 50

// Default number of rows to return per page
const DEFAULT_PAGE_SIZE = 100

const JSON_TYPES = ['json', 'jsonb']
const TEXT_TYPES = ['text', 'varchar']

interface GetTableRowsSqlArgs {
  table: TableLike
  filters?: Filter[]
  sorts?: Sort[]
  page?: number
  limit?: number
  maxCharacters?: number
  maxArraySize?: number
}

/**
 * Return the primary key columns if they exist, otherwise fall back to the
 * first column so that results have a stable, deterministic order.
 *
 * Returns an empty array when the entity has neither primary keys nor columns.
 */
export function getDefaultOrderByColumns(table: {
  primary_keys: Array<{ name: string }>
  columns: Array<{ name: string }>
}): string[] {
  const primaryKeys = table.primary_keys ?? []
  const columns = table.columns ?? []

  if (primaryKeys.length === 0 && columns.length === 0) {
    return []
  }

  if (primaryKeys.length > 0) {
    return primaryKeys.map((pk) => pk.name)
  }

  return [columns[0].name]
}

// Mirrors data/utils/pagination.ts so pg-meta stays framework agnostic
function getPagination(page?: number, size: number = DEFAULT_PAGE_SIZE) {
  const limit = size
  const from = page ? page * limit : 0
  const to = page ? from + size - 1 : size - 1
  return { from, to }
}

function isArrayColumn(column: Pick<PGColumn, 'data_type'>) {
  return (column.data_type ?? '').toLowerCase() === 'array'
}

function isTextOrJsonColumn(column: Pick<PGColumn, 'format'>) {
  const format = (column.format ?? '').toLowerCase()
  return TEXT_TYPES.includes(format) || JSON_TYPES.includes(format)
}

/**
 * Builds the SELECT expression for a single column.
 *
 * - Text/JSON columns are truncated to `maxCharacters` bytes to avoid pulling
 *   down huge payloads.
 * - Array columns are truncated to `maxArraySize` elements when their text
 *   representation exceeds `maxCharacters` bytes.
 * - Everything else is selected as-is.
 */
function getColumnSelectExpression(
  column: PGColumn,
  { maxCharacters, maxArraySize }: { maxCharacters: number; maxArraySize: number }
) {
  const col = ident(column.name)

  if (isArrayColumn(column)) {
    return `case
    when octet_length(${col}::text) > ${maxCharacters}
    then (select array_cat(${col}[1:${maxArraySize}]::text[], array['...']))::text[]
    else ${col}::text[]
end as ${col}`
  }

  if (isTextOrJsonColumn(column)) {
    return `case
    when octet_length(${col}::text) > ${maxCharacters}
    then left(${col}::text, ${maxCharacters}) || '...'
    else ${col}::text
end as ${col}`
  }

  return col
}

