 * entity (table, view, materialized view or foreign table).
 *
 * Handles large text/JSON values and array columns via truncation, and supports
 * filtering, sorting and pagination.
 */
export function getTableRowsSql({
  table,
  filters = [],
  sorts = [],
  page,
  limit,
  maxCharacters = MAX_CHARACTERS,
  maxArraySize = MAX_ARRAY_SIZE,
}: GetTableRowsSqlArgs): string {
