    .forEach((filter) => {
      queryChains = queryChains.filter(filter.column, filter.operator, filter.value)
    })

  if (sorts.length > 0) {
    sorts.forEach((sort) => {
      queryChains = queryChains.order(sort.table, sort.column, sort.ascending, sort.nullsFirst)
    })
  } else {
    const defaultOrderByColumns = getDefaultOrderByColumns({ primary_keys: primaryKeys, columns })
    defaultOrderByColumns.forEach((column) => {
      queryChains = queryChains.order(table.name, column, true, true)
    })
  }

  // getPagination expects a zero-based page index
  const { from, to } = getPagination((page ?? 1) - 1, limit)

  return queryChains.range(from, to).toSql()
}
